sourceProbe:
extends "res://retry-project-runtime.gd"
var gui_button: Button
var gui_count := 0
var sample_tick := 0
const NAV_BINDINGS = {"dddddddd-dddd-4ddd-8ddd-dddddddddddd":"99999999-9999-4999-8999-999999999991","12345678-1234-4234-8234-123456789abd":"12345678-1234-4234-8234-123456789ac3","00000385-1111-4111-8111-111111111111":"00000388-1111-4111-8111-111111111111"}
func _ready() -> void:
	super._ready()
	var layer := CanvasLayer.new()
	layer.layer = 2
	gui_button = Button.new()
	gui_button.text = "Test GUI consumes retry keys"
	gui_button.position = Vector2(280, 350)
	gui_button.size = Vector2(360, 48)
	gui_button.gui_input.connect(_consume_gui)
	layer.add_child(gui_button)
	add_child(layer)
	gui_button.grab_focus()
func _consume_gui(event: InputEvent) -> void:
	if event.is_action("retry_game"):
		if event.is_pressed() and not event.is_echo():
			gui_count += 1
		gui_button.accept_event()
		print("RETRY_GUI_HANDLED:" + JSON.stringify({"pressed":event.is_pressed(),"handled":get_viewport().is_input_handled()}))
func _input(event: InputEvent) -> void:
	if event is InputEventKey and event.pressed and not event.echo and event.physical_keycode == KEY_F8:
		gui_button.hide()
		get_viewport().set_input_as_handled()
func enter_scene(scene_id: String) -> void:
	super.enter_scene(scene_id)
	var ids: Array = []
	for behavior in current.find_children("behavior_*", "", true, false):
		ids.append(behavior.get_instance_id())
	print("RETRY_ENTER_SNAPSHOT:" + JSON.stringify({"sceneId":scene_id,"visit":visit_index,"state":shared_state,"actors":current.states(),"actorId":current.actors[0]["node"].get_instance_id(),"behaviorIds":ids,"hudId":current.get_node("VientoHUD2D").get_instance_id()}))
	call_deferred("capture_visit", visit_index, scene_id)
func leave_scene(reason: String, next_scene: String = "") -> void:
	var retained: Array = []
	for behavior in current.find_children("behavior_*", "", true, false):
		retained.append({"node":weakref(behavior),"port":behavior.get_meta("viento_project"),"retry":behavior.get_meta("viento_project_retry")})
	var hud = weakref(current.get_node("VientoHUD2D"))
	var actor = weakref(current.actors[0]["node"])
	var visit := visit_index
	super.leave_scene(reason, next_scene)
	var before := shared_state.duplicate()
	var revision := state_revision
	var checks: Array = []
	for row in retained:
		var port = row["port"]
		var retry = row["retry"]
		checks.append(row["node"].get_ref() == null and port.read_state("score") == null and not port.write_state("score", 999) and not port.erase_state("score") and not port.publish_event("game.audit", true) and not port.request_scene("dddddddd-dddd-4ddd-8ddd-dddddddddddd") and not retry.request_retry("12345678-1234-4234-8234-123456789abd", {"score":999}))
	var unchanged := before == shared_state and revision == state_revision
	assert(hud.get_ref() == null and actor.get_ref() == null and unchanged, "retry visit retained actor/HUD/state authority")
	for answer in checks:
		assert(answer, "stale behavior or port retained authority")
	print("RETRY_STALE_PORTS:" + JSON.stringify({"visit":visit,"checks":checks,"hudFreed":hud.get_ref() == null,"actorFreed":actor.get_ref() == null,"stateUnchanged":unchanged}))
func capture_visit(visit: int, scene_id: String) -> void:
	await RenderingServer.frame_post_draw
	if current != null and visit_index == visit and current_scene == scene_id:
		get_viewport().get_texture().get_image().save_png("/home/chiharukiryu/cdev/viento-studio/docs/test-results/scene-retry/native-final-2026-11-13/offline-keyboard" + "/visit-" + str(visit) + ".png")
func _process(delta: float) -> void:
	super._process(delta)
	if current == null:
		return
	sample_tick += 1
	if sample_tick % 3 != 0:
		return
	var hud = current.get_node("VientoHUD2D")
	var texts: Array = []
	for row in hud.rows:
		texts.append(row["label"].text)
	var gameplay = current.find_child("behavior_0000038a_1111_4111_8111_111111111111", true, false)
	var nav = current.find_child("behavior_" + NAV_BINDINGS[current_scene].replace("-", "_"), true, false)
	var action: bool = nav.has_method("_on_focus_entered")
	print("RETRY_SAMPLE:" + JSON.stringify({"sceneId":current_scene,"visit":visit_index,"state":shared_state,"revision":state_revision,"position":current.states()[0]["position"],"actorId":current.actors[0]["node"].get_instance_id(),"gameBehaviorId":gameplay.get_instance_id() if gameplay != null else 0,"ticks":gameplay.ticks if gameplay != null else 0,"audits":gameplay.audits if gameplay != null else 0,"subscriptions":event_bus.subscriptions.size(),"hudId":hud.get_instance_id(),"hudText":texts,"actionDown":Input.is_action_pressed("retry_game"),"focused":get_window().has_focus(),"armed":nav.get("_armed") if action else false,"guiCount":gui_count,"guiOpen":gui_button.visible if gui_button != null else false,"budget":execution_budget.snapshot()}, "", true, true))

